import React, { Component } from "react";
import "./App.css";

import { Typography } from "@material-ui/core";

import EventItem from "./EventItem.js";
/* fontSize: 45px */
class UpcomingEvents extends Component {
  render() {
    return (
      <div
        className="App-content"
        style={{ backgroundColor: "#2e3440" }}
        id="UpcomingEvents"
      >
        <Typography variant="h4" style={{ margin: "0.2em" }} class="titleTextFont">
          {" Upcoming Events "}
        </Typography>

        <EventItem
                    img="images/EventMicrophone.svg"
                    date="Tuesday 18/11/2025 - 7pm"
                    title="Karaoke Night"
                    location="Record Factory"
                    body="We've teamed up once again with MacSoc to bring you another unforgettable night of singing, laughter, and good vibes. Whether you're a seasoned performer or a first-time mic-grabber, come along and belt out your favourites with friends! Expect a great atmosphere, a wide song selection, and maybe even a surprise duet or two. Don’t miss it!"
    
                />

        <EventItem
                    img="images/EventWine.svg"
                    date="Thursday 27/11/2025 - 7pm"
                    title="Charity Ceilidh"
                    location="GUU Debates Chamber"
                    body="Join us and WiSTEM for a fantastic night of dancing! Tickets are £8 for members of either society, and £10 for non-members, with all profits going to Glasgow Women's Aid. Don't miss out on the raffle break in the middle of the ceilidh for a chance to win great prizes! Grab your tickets here. we can't wait to see you there!"
    
                />

        {/* <EventItem
        
                    img="images/RedQuark3.svg"
                    date="When: In the Past"
                      title={
                              <a
                                href="/Physoc_Coding_Tutorials.zip"
                                download
                                style={{ textDecoration: "none", color: "#ecefe4" }}
                              >
                                LaTeX and Python Coding Workshop
                              </a>
                            }

                    location="Where: 404 venue not found"
                    body="Are labs stressing you out? Do you feel like you need some help with coding? Unfortunately, you've missed our coding workshop for this semester - but don't worry! We've prepared some (hopefully) helpful material to guide you through the chaos, answer common questions, and boost your confidence. Check it out here: [insert link]"
 
        /> */}

        </div>

        
    );
  }
}

export default UpcomingEvents;

